update biz_lead set owner_id = #{ownerId}, dept_id = (select dept_id from sys_user where user_id = #{ownerId}),
pool_status = '0', disposition = 'ACTIVE', status = case when status = '0' then '1' else status end,
pool_reason = null, row_version = row_version + 1, update_by = #{updateBy}, update_time = sysdate()
where lead_id = #{leadId} and del_flag = '0' and status = #{expectedStatus}
and row_version = #{expectedRowVersion}

update biz_lead set owner_id = null, dept_id = null, pool_status = '1', disposition = 'PUBLIC_POOL',
status = '0', pool_reason = #{reason}, row_version = row_version + 1,
update_by = #{updateBy}, update_time = sysdate()
where lead_id = #{leadId} and del_flag = '0' and pool_status = '0'
and disposition = 'ACTIVE' and status = #{expectedStatus}
and row_version = #{expectedRowVersion}

update biz_lead set owner_id = #{ownerId}, dept_id = #{deptId}, pool_status = '0', disposition = 'ACTIVE',
status = case when status = '0' then '1' else status end, pool_reason = null,
row_version = row_version + 1, update_by = #{updateBy}, update_time = sysdate()
where lead_id = #{leadId} and pool_status = '1' and disposition = 'PUBLIC_POOL'
and owner_id is null and del_flag = '0' and status = #{expectedStatus}
and row_version = #{expectedRowVersion}

update biz_lead set customer_id = #{customerId}, status = '3', disposition = 'CONVERTED',
converted_time = sysdate(), row_version = row_version + 1, update_by = #{updateBy}, update_time = sysdate()
where lead_id = #{leadId} and del_flag = '0' and customer_id is null and status = #{expectedStatus}
and row_version = #{expectedRowVersion}

